ground-water-drawdown-theis-well-equatio.js:
(() => {
  'use strict';
  const qEl = document.getElementById('th-q'), tEl = document.getElementById('th-t'), sEl = document.getElementById('th-s');
  const rEl = document.getElementById('th-r'), tmEl = document.getElementById('th-time');
  const ddResEl = document.getElementById('th-res-dd'), uResEl = document.getElementById('th-res-u');

  function update() {
    const Q = parseFloat(qEl.value), T = parseFloat(tEl.value), S = parseFloat(sEl.value);
    const r = parseFloat(rEl.value), t = parseFloat(tmEl.value);

    if (isNaN(Q) || isNaN(T) || isNaN(S) || isNaN(r) || isNaN(t) || Q <= 0 || T <= 0 || S <= 0 || r <= 0 || t <= 0) return;

    // u = (r^2 * S) / (4 * T * t)
    const u = (Math.pow(r, 2) * S) / (4 * T * t);

    // Well function W(u) approximated via series: W(u) approx = -0.5772 - ln(u) + u - u^2/4 + ...
    let Wu = 0;
    if (u < 1.0) {
      Wu = -0.57721566 - Math.log(u) + u - (Math.pow(u, 2) / 4);
    } else {
      Wu = (Math.exp(-u) / u) * ((Math.pow(u, 2) + 2.334733 * u + 0.250621) / (Math.pow(u, 2) + 3.330657 * u + 1.681534));
    }

    // Drawdown s = (Q / (4 * pi * T)) * W(u)  [meters]
    const sDrawdown = (Q / (4 * Math.PI * T)) * Wu;

    ddResEl.textContent = 's = ' + sDrawdown.toFixed(2) + ' m (' + (sDrawdown * 3.28084).toFixed(1) + ' ft Water Table Drop)';
    uResEl.textContent = 'W(u) = ' + Wu.toFixed(2) + ' | u = ' + u.toExponential(3) + ' (r = ' + r + 'm after ' + t + ' days)';
  }

  [qEl, tEl, sEl, rEl, tmEl].forEach(el => el.addEventListener('input', update));
  update();
})();

groundwater-darcy-flux-hydraulic-conduct.js:
(() => {
  'use strict';
  const kEl = document.getElementById('gw-k'), dhEl = document.getElementById('gw-dh');
  const lEl = document.getElementById('gw-l'), neEl = document.getElementById('gw-ne');
  const qResEl = document.getElementById('gw-res-q'), vsResEl = document.getElementById('gw-res-vs');

  function update() {
    const K = parseFloat(kEl.value), dh = parseFloat(dhEl.value);
    const L = parseFloat(lEl.value), ne = parseFloat(neEl.value);

    if (isNaN(K) || isNaN(dh) || isNaN(L) || isNaN(ne) || K <= 0 || dh <= 0 || L <= 0 || ne <= 0 || ne > 1.0) return;

    // Hydraulic gradient i = dh / L
    const i = dh / L;

    // Darcy flux q = K * i  [m / day]
    const q = K * i;

    // Actual linear seepage velocity v_s = q / n_e  [m / day]
    const v_s = q / ne;
    const v_s_yr = v_s * 365.25;

    qResEl.textContent = 'Darcy Flux q = ' + q.toFixed(3) + ' m / day';
    vsResEl.textContent = 'Seepage Velocity v_s = ' + v_s.toFixed(3) + ' m/day (' + v_s_yr.toFixed(1) + ' m/yr | Gradient i = ' + i.toFixed(4) + ' @ n_e = ' + ne + ')';
  }

  [kEl, dhEl, lEl, neEl].forEach(el => el.addEventListener('input', update));
  update();
})();

gsm-lte-link-budget-indoor-outdoor-cover.js:
(function() {
  'use strict';
  var slug = 'gsm-lte-link-budget-indoor-outdoor-coverage-calculator';

  function el(id) {
    return document.getElementById(slug + '-' + id);
  }

  var outputEl = document.getElementById(slug + '-output');
  var msgEl = document.getElementById(slug + '-message');
  var btn = document.getElementById('primary-action-btn');
  var copyBtn = document.getElementById('copy-output');
  var clearBtn = document.getElementById('clear-text');

  function setMsg(t, err) {
    msgEl.textContent = t;
    msgEl.classList.toggle('is-error', !!err);
  }

  function calculate() {
    try {

      var pt = parseFloat(el('tx-power-dbm').value);
      var gt = parseFloat(el('tx-gain-dbi').value);
      var gr = parseFloat(el('rx-gain-dbi').value);
      var sens = parseFloat(el('rx-sens-dbm').value);
      var f_mhz = parseFloat(el('freq-mhz').value);
      if (isNaN(pt) || isNaN(gt) || isNaN(gr) || isNaN(sens) || isNaN(f_mhz) || f_mhz <= 0) {
        return { err: 'Please enter valid numerical values.' };
      }
      var mapl = pt + gt + gr - sens;
      var f_ghz = f_mhz / 1000;
      var max_d_km = Math.pow(10, (mapl - 92.45 - 20 * Math.log10(f_ghz)) / 20);
      var out = 'CELLULAR NETWORK LINK BUDGET & MAPL ANALYSIS\n';
      out += '=============================================\n';
      out += 'Tx Power              : ' + pt + ' dBm (20 W)\n';
      out += 'Tx Antenna Gain       : ' + gt + ' dBi\n';
      out += 'Rx Antenna Gain       : ' + gr + ' dBi\n';
      out += 'Receiver Sensitivity  : ' + sens + ' dBm\n';
      out += 'Frequency             : ' + f_mhz + ' MHz\n\n';
      out += 'RESULTS:\n';
      out += 'Max Allowable Path Loss (MAPL): ' + mapl.toFixed(2) + ' dB\n';
      out += 'Est. Max Free-Space Cell Radius: ' + max_d_km.toFixed(2) + ' km';
      return { out: out, msg: 'Cellular link budget computed successfully.' };

    } catch(e) {
      return { err: 'Error during calculation: ' + e.message };
    }
  }

  btn.addEventListener('click', function() {
    var res = calculate();
    if (res.err) {
      outputEl.value = '';
      copyBtn.disabled = true;
      setMsg(res.err, true);
    } else {
      outputEl.value = res.out;
      copyBtn.disabled = false;
      setMsg(res.msg || 'Calculation completed successfully.');
    }
  });

  copyBtn.addEventListener('click', function() {
    if (window.NikTool && typeof window.NikTool.copy === 'function') {
      window.NikTool.copy(outputEl.value, copyBtn);
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(outputEl.value);
    }
    setMsg('Result copied to clipboard.');
  });

  clearBtn.addEventListener('click', function() {
    var inputs = ['tx-power-dbm', 'tx-gain-dbi', 'rx-gain-dbi', 'rx-sens-dbm', 'freq-mhz'];
    inputs.forEach(function(id) {
      var elem = el(id);
      if (elem) elem.value = elem.defaultValue || '';
    });
    outputEl.value = '';
    copyBtn.disabled = true;
    setMsg('Cleared. Enter values above.');
  });
})();

