(() => {
  'use strict';
  const grossEl = document.getElementById('rgst-gross'), rateEl = document.getElementById('rgst-rate');
  const btn = document.getElementById('primary-action-btn'), clearBtn = document.getElementById('clear-action-btn');
  const msgEl = document.getElementById('tool-message'), resCard = document.getElementById('rgst-res-card');
  const resNet = document.getElementById('rgst-res-net'), resTax = document.getElementById('rgst-res-tax'), resHalf = document.getElementById('rgst-res-half');

  function setMsg(t, e) { msgEl.textContent = t; msgEl.className = 'message' + (e ? ' error' : ' success'); }

  btn.addEventListener('click', () => {
    const gross = parseFloat(grossEl.value);
    const rate = parseFloat(rateEl.value);

    if (isNaN(gross) || gross <= 0 || isNaN(rate) || rate <= 0) {
      setMsg('Please enter a valid positive gross amount.', true);
      resCard.style.display = 'none'; return;
    }

    // Base Price = Gross / (1 + Rate/100)
    const net = gross / (1 + (rate / 100));
    const tax = gross - net;
    const halfTax = tax / 2;

    resNet.textContent = '₹ ' + net.toFixed(2);
    resTax.textContent = '₹ ' + tax.toFixed(2);
    resHalf.textContent = '₹ ' + halfTax.toFixed(2) + ' (' + (rate / 2) + '%)';

    resCard.style.display = 'block';
    setMsg('Reverse GST calculated successfully.');
  });

  clearBtn.addEventListener('click', () => {
    grossEl.value = ''; resCard.style.display = 'none';
    msgEl.textContent = 'Ready. Enter parameters above.';
    msgEl.className = 'message';
  });
})();

h-bridge-spwm-inverter-modulation-index-.js:
(() => {
  'use strict';
  const vdcEl = document.getElementById('inv-vdc'), vctrlEl = document.getElementById('inv-vctrl'), vtriEl = document.getElementById('inv-vtri');
  const vrmsResEl = document.getElementById('inv-res-vrms'), maResEl = document.getElementById('inv-res-ma');

  function update() {
    const Vdc = parseFloat(vdcEl.value), Vctrl = parseFloat(vctrlEl.value), Vtri = parseFloat(vtriEl.value);
    if (isNaN(Vdc) || isNaN(Vctrl) || isNaN(Vtri) || Vdc <= 0 || Vctrl <= 0 || Vtri <= 0) return;

    // Amplitude modulation index m_a = Vctrl / Vtri
    const m_a = Vctrl / Vtri;

    let V_LL_rms = 0;
    let regimeDesc = '';
    let color = '#22543d';

    if (m_a <= 1.0) {
      // Linear modulation regime: V_LN,1,peak = m_a * Vdc / 2
      // V_LL,1,rms = sqrt(3) / sqrt(2) * (m_a * Vdc / 2) = (sqrt(3) / (2 * sqrt(2))) * m_a * Vdc
      V_LL_rms = (Math.sqrt(3) / (2 * Math.sqrt(2))) * m_a * Vdc;
      regimeDesc = 'LINEAR MODULATION (m_a = ' + m_a.toFixed(3) + ' ≤ 1.0: Pure Sine AC with Low THD)';
      color = '#22543d';
    } else if (m_a <= 3.24) {
      // Overmodulation regime
      const maxLinear = (Math.sqrt(3) / (2 * Math.sqrt(2))) * 1.0 * Vdc;
      const sixStep = (Math.sqrt(6) / Math.PI) * Vdc;
      V_LL_rms = maxLinear + ((sixStep - maxLinear) * ((m_a - 1.0) / 2.24));
      regimeDesc = 'OVERMODULATION (1.0 < m_a < 3.24: Non-linear voltage gain with lower-order harmonics)';
      color = '#d97706';
    } else {
      // Six-step square wave limit: V_LL,rms = sqrt(6)/pi * Vdc = 0.7797 * Vdc
      V_LL_rms = (Math.sqrt(6) / Math.PI) * Vdc;
      regimeDesc = 'SIX-STEP SQUARE WAVE OPERATION (m_a >> 1: Maximum Voltage Utilization 0.78·V_dc)';
      color = '#c53030';
    }

    const V_LN_rms = V_LL_rms / Math.sqrt(3);

    vrmsResEl.textContent = 'V_LL = ' + V_LL_rms.toFixed(1) + ' V RMS (Phase V_LN = ' + V_LN_rms.toFixed(1) + ' V)';
    maResEl.textContent = regimeDesc;
    maResEl.style.color = color;
  }

  [vdcEl, vctrlEl, vtriEl].forEach(el => el.addEventListener('input', update));
  update();
})();

h-index-i10-index-academic-research-cita.js:
(() => {
  'use strict';
  const cEl = document.getElementById('hi-cites');
  const hResEl = document.getElementById('hi-res-h'), smResEl = document.getElementById('hi-res-sum');

  function update() {
    const raw = (cEl.value || '').split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n) && n >= 0);
    if (raw.length === 0) return;

    raw.sort((a, b) => b - a);

    let h = 0;
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] >= i + 1) h = i + 1;
      else break;
    }

    const i10 = raw.filter(c => c >= 10).length;
    const totalCites = raw.reduce((a, b) => a + b, 0);
    const avgCites = totalCites / raw.length;

    hResEl.textContent = 'h-index = ' + h + ' | i10-index = ' + i10;
    smResEl.textContent = 'Total Citations = ' + totalCites.toLocaleString() + ' | Average = ' + avgCites.toFixed(2) + ' Citations/Paper (Total: ' + raw.length + ' Papers)';
  }

  cEl.addEventListener('input', update);
  update();
})();

hagen-poiseuille-laminar-flow-capillary-.js:
(() => {
  'use strict';
  const rEl = document.getElementById('hp-r'), lEl = document.getElementById('hp-l');
  const dpEl = document.getElementById('hp-dp'), muEl = document.getElementById('hp-mu');
  const qResEl = document.getElementById('hp-res-q'), shResEl = document.getElementById('hp-res-shear');

  function update() {
    const R_mm = parseFloat(rEl.value), L_mm = parseFloat(lEl.value);
    const dP_kPa = parseFloat(dpEl.value), mu_cP = parseFloat(muEl.value);

    if (isNaN(R_mm) || isNaN(L_mm) || isNaN(dP_kPa) || isNaN(mu_cP) || R_mm <= 0 || L_mm <= 0 || dP_kPa <= 0 || mu_cP <= 0) return;

    const R_m = R_mm * 1e-3;
    const L_m = L_mm * 1e-3;
    const dP_Pa = dP_kPa * 1000.0;
    const mu_Pa_s = mu_cP * 1e-3;

    // Hagen-Poiseuille: Q = ( pi * R^4 * dP ) / ( 8 * mu * L )  [m^3 / s]
    const Q_m3_s = (Math.PI * Math.pow(R_m, 4) * dP_Pa) / (8.0 * mu_Pa_s * L_m);
    const Q_mL_min = Q_m3_s * 1e6 * 60.0;

    // Mean velocity v = Q / (pi * R^2)
    const v_mean = Q_m3_s / (Math.PI * Math.pow(R_m, 2));

    // Wall shear stress: tau_w = ( R * dP ) / ( 2 * L )  [Pa]
    const tau_w = (R_m * dP_Pa) / (2.0 * L_m);

    qResEl.textContent = 'Flow Rate Q = ' + Q_mL_min.toFixed(2) + ' mL / min';
    shResEl.textContent = 'Wall Shear τ_w = ' + tau_w.toFixed(1) + ' Pa | Mean Velocity v = ' + v_mean.toFixed(3) + ' m/s (R=' + R_mm + ' mm @ ' + mu_cP + ' cP)';
  }

  [rEl, lEl, dpEl, muEl].forEach(el => el.addEventListener('input', update));
  update();
})();

