(() => {
  'use strict';
  const c0El = document.getElementById('fo-c0'), kEl = document.getElementById('fo-k'), tEl = document.getElementById('fo-t');
  const ctResEl = document.getElementById('fo-res-ct'), thResEl = document.getElementById('fo-res-thalf');

  function update() {
    const C0 = parseFloat(c0El.value), k = parseFloat(kEl.value), t = parseFloat(tEl.value);
    if (isNaN(C0) || isNaN(k) || isNaN(t) || C0 <= 0 || k <= 0 || t < 0) return;

    // First order: C_t = C0 * exp(-k * t)
    const Ct = C0 * Math.exp(-k * t);
    const tHalf = Math.LN2 / k;
    const pctRemain = (Ct / C0) * 100;
    const halfLivesPassed = t / tHalf;

    ctResEl.textContent = Ct.toFixed(2) + ' (' + pctRemain.toFixed(1) + '% Remaining)';
    thResEl.textContent = 't₁/₂ = ' + tHalf.toFixed(2) + ' time units (' + halfLivesPassed.toFixed(2) + ' Half-Lives Passed)';
  }

  [c0El, kEl, tEl].forEach(el => el.addEventListener('input', update));
  update();
})();

hall-effect-carrier-density-mobility-coe.js:
(() => {
  'use strict';
  const iEl = document.getElementById('he-i'), bEl = document.getElementById('he-b');
  const tEl = document.getElementById('he-t'), vhEl = document.getElementById('he-vh');
  const nResEl = document.getElementById('he-res-n'), rhResEl = document.getElementById('he-res-rh');

  const q = 1.602176634e-19; // C

  function update() {
    const I_mA = parseFloat(iEl.value), B_T = parseFloat(bEl.value);
    const t_um = parseFloat(tEl.value), V_H_mV = parseFloat(vhEl.value);

    if (isNaN(I_mA) || isNaN(B_T) || isNaN(t_um) || isNaN(V_H_mV) || I_mA === 0 || B_T === 0 || t_um <= 0 || V_H_mV === 0) return;

    const I_A = I_mA * 1e-3;
    const t_cm = t_um * 1e-4;
    const V_H_V = V_H_mV * 1e-3;

    // Hall coefficient: R_H = ( V_H * t ) / ( I * B )  [m^3 / C -> cm^3 / C]
    // V_H in V, t in cm, I in A, B in T (= V*s/m^2):
    // R_H (cm^3 / C) = ( V_H * t_cm ) / ( I_A * B_T ) * 1e-4 * 1e6 = (V_H * t_cm) / (I_A * B_T)
    const R_H_cm3_C = (V_H_V * t_cm) / (I_A * B_T) * 1e8 * 1e-4; // standard unit scaling

    // Carrier concentration: n or p = 1 / ( q * |R_H| )  [cm^-3]
    const carrier_density = 1.0 / (q * Math.abs(R_H_cm3_C));

    const is_n_type = V_H_mV < 0;

    nResEl.textContent = (is_n_type ? 'n-Type Electrons: n = ' : 'p-Type Holes: p = ') + carrier_density.toExponential(2) + ' cm⁻³';
    nResEl.style.color = '#22543d';
    rhResEl.textContent = 'Hall Coefficient R_H = ' + R_H_cm3_C.toFixed(1) + ' cm³/C (' + (is_n_type ? 'Electrons (V_H < 0)' : 'Holes (V_H > 0)') + ' @ B=' + B_T + ' T)';
  }

  [iEl, bEl, tEl, vhEl].forEach(el => el.addEventListener('input', update));
  update();
})();

hall-effect-thruster-anode-efficiency-sp.js:
(() => {
  'use strict';
  const tEl = document.getElementById('het-t'), pEl = document.getElementById('het-p'), mEl = document.getElementById('het-mdot');
  const etaResEl = document.getElementById('het-res-eta'), ispResEl = document.getElementById('het-res-isp');

  const g0 = 9.80665;

  function update() {
    const T_mN = parseFloat(tEl.value), P_kW = parseFloat(pEl.value), mdot_mg_s = parseFloat(mEl.value);
    if (isNaN(T_mN) || isNaN(P_kW) || isNaN(mdot_mg_s) || T_mN <= 0 || P_kW <= 0 || mdot_mg_s <= 0) return;

    const T_N = T_mN * 1e-3;
    const P_W = P_kW * 1000.0;
    const mdot_kg_s = mdot_mg_s * 1e-6;

    // Specific impulse I_sp = T / ( mdot * g0 )  [seconds]
    const I_sp = T_N / (mdot_kg_s * g0);
    // Exhaust velocity v_e = I_sp * g0  [m / s -> km / s]
    const v_e_km_s = (I_sp * g0) / 1000.0;

    // Anode efficiency eta_a = T^2 / ( 2 * mdot * P_d )
    const eta_a = Math.pow(T_N, 2) / (2.0 * mdot_kg_s * P_W);
    const eta_pct = eta_a * 100.0;

    // Thrust-to-power ratio T/P in mN / kW
    const T_P = T_mN / P_kW;

    etaResEl.textContent = 'η_a = ' + eta_pct.toFixed(1) + '% Anode Efficiency';
