(() => {
  'use strict';
  const inEl = document.getElementById('sha-input'), outEl = document.getElementById('sha-output');
  const copyBtn = document.getElementById('copy-sha-btn');

  async function update() {
    const text = inEl.value;
    if (!text) { outEl.value = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'; return; }

    const encoder = new TextEncoder();
    const data = encoder.encode(text);
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');

    outEl.value = hashHex;
  }

  inEl.addEventListener('input', update);
  update();

  copyBtn.addEventListener('click', () => {
    if (window.NikTool && typeof window.NikTool.copy === 'function') {
      window.NikTool.copy(outEl.value, copyBtn);
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(outEl.value);
    }
  });
})();

haversine-great-circle-distance-calculat.js:
(() => {
  'use strict';
  const lat1El = document.getElementById('hav-lat1'), lon1El = document.getElementById('hav-lon1');
  const lat2El = document.getElementById('hav-lat2'), lon2El = document.getElementById('hav-lon2');
  const kmResEl = document.getElementById('hav-res-km'), nmResEl = document.getElementById('hav-res-nm');

  const R_Earth_km = 6371.0;

  function toRad(deg) { return (deg * Math.PI) / 180; }

  function update() {
    const lat1 = parseFloat(lat1El.value), lon1 = parseFloat(lon1El.value);
    const lat2 = parseFloat(lat2El.value), lon2 = parseFloat(lon2El.value);

    if (isNaN(lat1) || isNaN(lon1) || isNaN(lat2) || isNaN(lon2)) return;

    const phi1 = toRad(lat1), phi2 = toRad(lat2);
    const dPhi = toRad(lat2 - lat1);
    const dLam = toRad(lon2 - lon1);

    // a = sin^2(dPhi/2) + cos(phi1) * cos(phi2) * sin^2(dLam/2)
    const a = Math.pow(Math.sin(dPhi / 2), 2) + Math.cos(phi1) * Math.cos(phi2) * Math.pow(Math.sin(dLam / 2), 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    const distKm = R_Earth_km * c;
    const distMiles = distKm * 0.621371;
    const distNm = distKm * 0.539957;

    kmResEl.textContent = Math.round(distKm).toLocaleString() + ' km (' + Math.round(distMiles).toLocaleString() + ' Miles)';
    nmResEl.textContent = Math.round(distNm).toLocaleString() + ' Nautical Miles (Flight Path)';
  }

  [lat1El, lon1El, lat2El, lon2El].forEach(el => el.addEventListener('input', update));
  update();
})();

hawking-radiation-black-hole-temperature.js:
(() => {
  'use strict';
  const mEl = document.getElementById('hw-mass'), tpEl = document.getElementById('hw-type');
  const tResEl = document.getElementById('hw-res-temp'), lfResEl = document.getElementById('hw-res-life');

  const M_sun_kg = 1.98847e30;
  // Hawking temp constant: T_H = (hbar * c^3) / (8 * pi * G * M * k_B) approx 1.227e23 / M (kg)
  const T_const = 1.227e23; // K * kg

  // Lifetime constant: t_evap = (5120 * pi * G^2 * M^3) / (hbar * c^4) approx 2.098e-16 * M^3 (seconds)
  // In years: t_evap_yr approx 2.098e-16 * M^3 / 3.15576e7 approx 6.648e-24 * M^3 (years)

  function update() {
    let mass_input = parseFloat(mEl.value);
    const isSolar = tpEl.value === 'msun';

    if (isNaN(mass_input) || mass_input <= 0) return;

    const M_kg = isSolar ? mass_input * M_sun_kg : mass_input;

    // Hawking temperature: T_H = T_const / M_kg  [K]
    const T_H_K = T_const / M_kg;

    // Lifetime in years: t_yr = 6.648e-24 * (M_kg)^3
    const t_evap_yr = 6.648e-24 * Math.pow(M_kg, 3);

    // Radiative power: P = (hbar * c^6) / (15360 * pi * G^2 * M^2) approx 3.562e32 / M^2  [Watts]
    const P_watts = 3.562e32 / Math.pow(M_kg, 2);

    tResEl.textContent = 'Hawking Temp T_H = ' + T_H_K.toExponential(2) + ' K';
    lfResEl.textContent = 'Lifetime t_evap = ' + t_evap_yr.toExponential(2) + ' Years | Power = ' + P_watts.toExponential(2) + ' Watts (M = ' + (isSolar ? mass_input + ' M_sun' : M_kg.toExponential(2) + ' kg') + ')';
  }

  mEl.addEventListener('input', update);
  tpEl.addEventListener('change', update);
  update();
})();

