    // Center of pressure y_cp = hc + (Ixc / (hc * A))
    const yCp = hc + (Ixc / (hc * area));

    fResEl.textContent = forceKn.toFixed(2) + ' kN';
    cpResEl.textContent = yCp.toFixed(2) + ' meters deep';
    tResEl.textContent = forceTons.toFixed(2) + ' Metric Tons';
  }

