i2c-pullup-resistor-bus-capacitance-calc.js:
(() => {
  'use strict';
  const vddEl = document.getElementById('i2c-vdd'), cbEl = document.getElementById('i2c-cb'), modeEl = document.getElementById('i2c-mode');
  const recEl = document.getElementById('i2c-res-rec'), ranEl = document.getElementById('i2c-res-range');

  function update() {
    const vdd = parseFloat(vddEl.value), cbPf = parseFloat(cbEl.value), trMaxNs = parseFloat(modeEl.value);
    if (isNaN(vdd) || isNaN(cbPf) || isNaN(trMaxNs) || vdd <= 0.8 || cbPf <= 0 || trMaxNs <= 0) return;

    const cbF = cbPf * 1e-12;
    const trMaxS = trMaxNs * 1e-9;

    // NXP I2C Specification:
    // R_min = (Vdd - Vol_max) / Iol = (Vdd - 0.4V) / 3mA
    const rMin = (vdd - 0.4) / 0.003;
    // R_max = tr_max / (0.8473 * Cb)
    const rMax = trMaxS / (0.8473 * cbF);

    const rMinK = rMin / 1000;
    const rMaxK = rMax / 1000;

    let recK = Math.sqrt(rMinK * rMaxK);
    const standardE24 = [1.0, 1.2, 1.5, 1.8, 2.2, 2.7, 3.3, 3.9, 4.7, 5.6, 6.8, 8.2, 10.0];
    let bestFit = 2.2;
    let minDiff = Infinity;
    for (const val of standardE24) {
      if (val >= rMinK && val <= rMaxK) {
        const diff = Math.abs(val - recK);
        if (diff < minDiff) { minDiff = diff; bestFit = val; }
      }
    }

    if (rMin > rMax) {
      recEl.textContent = 'Bus Capacitance Too High!';
      recEl.style.color = '#c53030';
      ranEl.textContent = 'Reduce PCB trace length or use I2C bus buffer';
    } else {
      recEl.textContent = bestFit + ' kΩ (E24 Standard)';
      recEl.style.color = '#22543d';
      ranEl.textContent = Math.round(rMin) + ' Ω to ' + (rMaxK).toFixed(2) + ' kΩ';
    }
  }

  [vddEl, cbEl, modeEl].forEach(el => el.addEventListener('input', update));
  update();
})();

ib-biology-chi-square-goodness-of-fit-di.js:
(() => {
  'use strict';
  const mEl = document.getElementById('chi-model');
  const o1El = document.getElementById('chi-o1'), o2El = document.getElementById('chi-o2');
  const o3El = document.getElementById('chi-o3'), o4El = document.getElementById('chi-o4');
  const grpO3 = document.getElementById('chi-grp-o3'), grpO4 = document.getElementById('chi-grp-o4');
  const stResEl = document.getElementById('chi-res-stat'), pResEl = document.getElementById('chi-res-p');

  // Critical values at alpha = 0.05 for df = 1, 2, 3
  const CRIT = { 1: 3.841, 2: 5.991, 3: 7.815 };

  function update() {
    const model = mEl.value;
    const o1 = parseFloat(o1El.value) || 0;
    const o2 = parseFloat(o2El.value) || 0;
    const o3 = parseFloat(o3El.value) || 0;
    const o4 = parseFloat(o4El.value) || 0;

    let observed = [], ratios = [];

    if (model === 'dihybrid') {
      observed = [o1, o2, o3, o4];
      ratios = [9/16, 3/16, 3/16, 1/16];
    } else if (model === 'monohybrid') {
      observed = [o1, o2];
      ratios = [3/4, 1/4];
    } else if (model === 'codominant') {
      observed = [o1, o2, o3];
      ratios = [1/4, 2/4, 1/4];
    } else if (model === 'testcross') {
      observed = [o1, o2, o3, o4];
      ratios = [1/4, 1/4, 1/4, 1/4];
    }

    const totalObs = observed.reduce((a, b) => a + b, 0);
    if (totalObs <= 0) return;

    let chi2 = 0;
    for (let i = 0; i < observed.length; i++) {
      const exp = totalObs * ratios[i];
      chi2 += Math.pow(observed[i] - exp, 2) / exp;
    }

    const df = observed.length - 1;
    const critVal = CRIT[df] || 3.841;

    let decision = '';
    let color = '#22543d';

    if (chi2 <= critVal) {
      decision = 'FAIL TO REJECT H₀ (χ² = ' + chi2.toFixed(3) + ' ≤ Critical ' + critVal + '): Observed data matches expected Mendelian inheritance ratio at p > 0.05';
      color = '#22543d';
    } else {
      decision = 'REJECT H₀ (χ² = ' + chi2.toFixed(3) + ' > Critical ' + critVal + '): Significant deviation! Genes may be linked on the same chromosome or lethal';
      color = '#c53030';
    }

    stResEl.textContent = 'χ² = ' + chi2.toFixed(3) + ' (df = ' + df + ', N = ' + totalObs + ')';
    pResEl.textContent = decision;
    pResEl.style.color = color;
  }

  [mEl, o1El, o2El, o3El, o4El].forEach(el => el.addEventListener('input', update));
