    const gyro_integrated = th_prev + (omega_gyro * dt);

    // Complementary Filter equation:
    // theta_k = alpha * ( theta_{k-1} + omega_gyro * dt ) + ( 1 - alpha ) * theta_accel
    const part_gyro = alpha * gyro_integrated;
    const part_accel = (1.0 - alpha) * th_accel;
    const theta_fused = part_gyro + part_accel;

    fsResEl.textContent = 'Fused Tilt Angle θ_k = ' + theta_fused.toFixed(2) + '°';
    ptResEl.textContent = 'Gyro Track = ' + part_gyro.toFixed(2) + '° (' + (alpha * 100).toFixed(0) + '%) | Accel Drift Fix = ' + part_accel.toFixed(2) + '° (' + ((1.0 - alpha) * 100).toFixed(0) + '% @ ' + (1.0/dt).toFixed(0) + ' Hz)';
  }

  [thpEl, gyEl, dtEl, acEl, alEl].forEach(el => el.addEventListener('input', update));
  update();
})();

inertial-navigation-dead-reckoning-drift.js:
(() => {
  'use strict';
  const baEl = document.getElementById('ins-ba'), bgEl = document.getElementById('ins-bg'), tmEl = document.getElementById('ins-time');
  const erResEl = document.getElementById('ins-res-err'), spResEl = document.getElementById('ins-res-split');

  const g = 9.80665;

  function update() {
    const ba_mg = parseFloat(baEl.value), bg_deg_hr = parseFloat(bgEl.value), tMin = parseFloat(tmEl.value);
    if (isNaN(ba_mg) || isNaN(bg_deg_hr) || isNaN(tMin) || ba_mg < 0 || bg_deg_hr < 0 || tMin <= 0) return;

    const tSec = tMin * 60;

    // Accelerometer bias in m / s^2: ba_mg * 1e-3 * g
    const ba_ms2 = ba_mg * 1e-3 * g;
    // Position error from accelerometer bias = 1/2 * ba * t^2
    const err_accel_m = 0.5 * ba_ms2 * Math.pow(tSec, 2);

    // Gyro bias in rad / s: (bg_deg_hr * pi/180) / 3600
    const bg_rad_s = ((bg_deg_hr * Math.PI) / 180) / 3600;
    // Position error from gyro tilt bias coupling with gravity = 1/6 * bg * g * t^3
    const err_gyro_m = (1 / 6) * bg_rad_s * g * Math.pow(tSec, 3);

    const totalErrorM = err_accel_m + err_gyro_m;
    const totalErrorKm = totalErrorM / 1000;

    let errStr = '';
    if (totalErrorM < 1000) errStr = totalErrorM.toFixed(1) + ' m';
    else errStr = totalErrorKm.toFixed(2) + ' km (' + Math.round(totalErrorM).toLocaleString() + ' m)';

    erResEl.textContent = errStr + ' Position Drift';
    spResEl.textContent = 'Accel: ' + (err_accel_m < 1000 ? err_accel_m.toFixed(1) + 'm' : (err_accel_m/1000).toFixed(2) + 'km') + ' (t²) | Gyro: ' + (err_gyro_m < 1000 ? err_gyro_m.toFixed(1) + 'm' : (err_gyro_m/1000).toFixed(2) + 'km') + ' (t³ coupling with 1g gravity)';
  }

  [baEl, bgEl, tmEl].forEach(el => el.addEventListener('input', update));
  update();
})();

infinite-slope-stability-factor-of-safet.js:
(() => {
  'use strict';
  const btEl = document.getElementById('is-beta'), hEl = document.getElementById('is-h');
  const cEl = document.getElementById('is-c'), phiEl = document.getElementById('is-phi'), hwEl = document.getElementById('is-hw');
  const fsResEl = document.getElementById('is-res-fs'), bkResEl = document.getElementById('is-res-break');

  const gamma = 19.0; // kN / m^3
  const gamma_w = 9.81; // kN / m^3

  function update() {
    const beta_deg = parseFloat(btEl.value), H = parseFloat(hEl.value);
    const c = parseFloat(cEl.value), phi_deg = parseFloat(phiEl.value), hw_ratio = parseFloat(hwEl.value);

    if (isNaN(beta_deg) || isNaN(H) || isNaN(c) || isNaN(phi_deg) || isNaN(hw_ratio) || beta_deg <= 0 || beta_deg >= 90 || H <= 0 || c < 0 || phi_deg < 0 || hw_ratio < 0 || hw_ratio > 1) return;

    const beta = (beta_deg * Math.PI) / 180.0;
    const phi = (phi_deg * Math.PI) / 180.0;

    // Driving shear stress: tau_d = gamma * H * sin(beta) * cos(beta)
    const tau_driving = gamma * H * Math.sin(beta) * Math.cos(beta);

    // Cohesion component: c / tau_d
    const FS_c = c / tau_driving;

    // Frictional component: ( tan(phi) / tan(beta) ) * ( 1 - (gamma_w / gamma) * hw_ratio )
    const FS_phi = (Math.tan(phi) / Math.tan(beta)) * (1.0 - ((gamma_w / gamma) * hw_ratio));

    const FS = FS_c + FS_phi;

    // Full saturation FS (hw_ratio = 1):
    const FS_sat = FS_c + (Math.tan(phi) / Math.tan(beta)) * (1.0 - (gamma_w / gamma));

    let status = '', color = '#22543d';
    if (FS >= 1.5) { status = 'STABLE (FS ≥ 1.5: Adequate safety margin)'; color = '#22543d'; }
    else if (FS >= 1.0) { status = 'MARGINALLY STABLE (1.0 ≤ FS < 1.5: Landslide risk if saturated)'; color = '#ea580c'; }
    else { status = 'ACTIVE LANDSLIDE SLOPE FAILURE (FS < 1.0)'; color = '#c53030'; }

    fsResEl.textContent = 'Factor of Safety FS = ' + FS.toFixed(2) + ' (' + status.split(' (')[0] + ')';
    fsResEl.style.color = color;
    bkResEl.textContent = 'Cohesion = +' + FS_c.toFixed(2) + ' | Friction = +' + FS_phi.toFixed(2) + ' (If fully saturated h_w=H: FS drops to ' + FS_sat.toFixed(2) + ')';
  }

  [btEl, hEl, cEl, phiEl, hwEl].forEach(el => el.addEventListener('input', update));
  update();
})();

