    realEl.textContent = '$' + Math.round(realValue).toLocaleString();
    lossEl.textContent = '-' + lossPct.toFixed(2) + '% Lost to Inflation';
  }

  [aEl, rEl, yEl].forEach(el => el.addEventListener('input', update));
  update();
})();

