    niResEl.textContent = 'Intrinsic n_i = ' + n_i.toExponential(2) + ' cm⁻³';
    eiResEl.textContent = 'Fermi Offset (E_i - E_mid) = ' + (offset_meV >= 0 ? '+' : '') + offset_meV.toFixed(1) + ' meV | kT = ' + (kT_eV * 1000).toFixed(2) + ' meV (E_g = ' + E_g + ' eV @ ' + T_K + ' K)';
