    const Y_star = (k * (I0 + G) + (0.2 * k * MP)) / (1.0 + (0.2 * k));
    const r_star = Math.max(0, (0.01 * Y_star) - (MP / 100.0));

    eqResEl.textContent = 'Income Y* = $' + Math.round(Y_star).toLocaleString() + ' B | Rate r* = ' + r_star.toFixed(2) + '%';
