})();

joule-thomson-cooling-coefficient-liquef.js:
(() => {
  'use strict';
  const gasEl = document.getElementById('jt-gas'), dpEl = document.getElementById('jt-dp');
  const dtResEl = document.getElementById('jt-res-dt'), cResEl = document.getElementById('jt-res-cool');

  const GASES = {
    'n2':  { mu_jt: +0.25, t_inv: 621, name: 'Nitrogen (N₂)' },
    'ch4': { mu_jt: +0.43, t_inv: 960, name: 'Methane (CH₄)' },
    'air': { mu_jt: +0.22, t_inv: 603, name: 'Compressed Air' },
    'he':  { mu_jt: -0.06, t_inv: 45,  name: 'Helium (He)' },
    'h2':  { mu_jt: -0.03, t_inv: 202, name: 'Hydrogen (H₂)' }
  };

  function update() {
    const g = GASES[gasEl.value];
    const dP = parseFloat(dpEl.value);

    if (isNaN(dP) || dP <= 0) return;

    // Delta_T = mu_JT * (-dP) where expansion is pressure drop
    const deltaT = -g.mu_jt * dP;

    let regime = '';
    let color = '#22543d';

    if (g.mu_jt > 0) {
      regime = 'COOLING REGIME (μ_JT = +' + g.mu_jt + ' K/bar): Throttling produces -' + Math.abs(deltaT).toFixed(1) + '°C cooling drop';
      color = '#22543d';
    } else {
      regime = 'HEATING REGIME (μ_JT = ' + g.mu_jt + ' K/bar): Gas HEATS UP by +' + Math.abs(deltaT).toFixed(1) + '°C upon expansion (Must pre-cool below ' + g.t_inv + ' K)';
      color = '#c53030';
    }

    dtResEl.textContent = 'ΔT = ' + (deltaT > 0 ? '+' : '') + deltaT.toFixed(1) + ' °C (' + (deltaT < 0 ? 'Cooling' : 'Heating') + ')';
    dtResEl.style.color = color;
    cResEl.textContent = regime + ' | Inversion Temp: ' + g.t_inv + ' K (' + (g.t_inv - 273.15).toFixed(0) + '°C)';
    cResEl.style.color = color;
  }

  gasEl.addEventListener('change', update);
  dpEl.addEventListener('input', update);
  update();
})();

jump-height-ground-reaction-force-calcul.js:
(() => {
  'use strict';
  const mEl = document.getElementById('jmp-mass'), vEl = document.getElementById('jmp-v'), dEl = document.getElementById('jmp-d');
  const hResEl = document.getElementById('jmp-res-ht'), gResEl = document.getElementById('jmp-res-grf');

  const g = 9.80665;

  function update() {
    const mass = parseFloat(mEl.value), vTakeoff = parseFloat(vEl.value), dPushCm = parseFloat(dEl.value);
    if (isNaN(mass) || isNaN(vTakeoff) || isNaN(dPushCm) || mass <= 0 || vTakeoff <= 0 || dPushCm <= 0) return;

    // Jump height h = v^2 / (2*g)  [meters]
    const hMeters = Math.pow(vTakeoff, 2) / (2 * g);
    const hCm = hMeters * 100;
    const hInches = hCm / 2.54;

    // Flight hang time = 2 * (v / g)
    const hangTime = 2 * (vTakeoff / g);

    // Push-off acceleration a = v^2 / (2 * d_push)
    const dPushM = dPushCm / 100;
    const accel = Math.pow(vTakeoff, 2) / (2 * dPushM);

    // Ground reaction force GRF = mass * (g + a)
    const GRF = mass * (g + accel);
    const bwRatio = GRF / (mass * g);

    hResEl.textContent = hCm.toFixed(1) + ' cm (' + hInches.toFixed(1) + ' inches Jump)';
    gResEl.textContent = 'Peak GRF: ' + Math.round(GRF).toLocaleString() + ' N (' + bwRatio.toFixed(2) + '× Bodyweight) | Hang Time: ' + hangTime.toFixed(3) + ' s';
  }

  [mEl, vEl, dEl].forEach(el => el.addEventListener('input', update));
  update();
})();

jwt-debugger.js:
(() => {
  'use strict';

  const inputEl = document.getElementById('jwt-input');
  const decodeBtn = document.getElementById('primary-action-btn');
  const sampleBtn = document.getElementById('sample-token-btn');
  const clearBtn = document.getElementById('clear-btn');
  const msgEl = document.getElementById('jwt-message');
  const detailsCard = document.getElementById('jwt-details-card');

  const statusBadge = document.getElementById('jwt-status-badge');
  const algBadge = document.getElementById('jwt-alg-badge');
  const expBadge = document.getElementById('jwt-exp-badge');
  const iatBadge = document.getElementById('jwt-iat-badge');

  const headerOutput = document.getElementById('jwt-header-output');
  const payloadOutput = document.getElementById('jwt-payload-output');
  const signatureOutput = document.getElementById('jwt-signature-output');

  const copyHeaderBtn = document.getElementById('copy-header-btn');
  const copyPayloadBtn = document.getElementById('copy-payload-btn');

  if (!inputEl || !decodeBtn || !msgEl) {
    console.error('JWT Debugger: Missing required elements.');
    return;
  }

  function setMsg(text, type = '') {
    msgEl.textContent = text;
    msgEl.className = `message${type ? ` ${type}` : ''}`;
  }

  function base64UrlDecode(str) {
    let base64 = str.replace(/-/g, '+').replace(/_/g, '/');
    while (base64.length % 4) {
      base64 += '=';
    }
    const rawBinary = atob(base64);
    const bytes = new Uint8Array(rawBinary.length);
    for (let i = 0; i < rawBinary.length; i++) {
      bytes[i] = rawBinary.charCodeAt(i);
    }
    return new TextDecoder('utf-8').decode(bytes);
  }

  function base64UrlEncode(str) {
    const bytes = new TextEncoder().encode(str);
    let binary = '';
    for (let i = 0; i < bytes.length; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }

  function formatTimestamp(timestampInSeconds) {
    if (!timestampInSeconds || isNaN(timestampInSeconds)) return 'N/A';
    const date = new Date(timestampInSeconds * 1000);
    return date.toLocaleString();
  }

  function decodeJWT() {
    const raw = inputEl.value.trim();
    if (!raw) {
      setMsg('Please paste a JWT token to decode.', 'error');
      detailsCard.style.display = 'none';
      return;
    }

    const parts = raw.split('.');
    if (parts.length !== 3) {
      setMsg('Invalid JWT format. A valid token must have 3 parts separated by dots (header.payload.signature).', 'error');
      detailsCard.style.display = 'none';
      return;
    }

    try {
      const headerStr = base64UrlDecode(parts[0]);
      const headerObj = JSON.parse(headerStr);
      headerOutput.value = JSON.stringify(headerObj, null, 2);

      const payloadStr = base64UrlDecode(parts[1]);
      const payloadObj = JSON.parse(payloadStr);
      payloadOutput.value = JSON.stringify(payloadObj, null, 2);

      signatureOutput.value = parts[2] || '(None / Unsigned)';

      // Badges
      algBadge.textContent = headerObj.alg || 'None';

      const nowSec = Math.floor(Date.now() / 1000);
      if (payloadObj.exp) {
        expBadge.textContent = formatTimestamp(payloadObj.exp);
        if (payloadObj.exp < nowSec) {
          statusBadge.textContent = 'Expired';
          statusBadge.style.color = '#c53030';
        } else {
          statusBadge.textContent = 'Active (Valid)';
          statusBadge.style.color = '#22543d';
        }
      } else {
        expBadge.textContent = 'No Expiration (exp)';
        statusBadge.textContent = 'Valid (No Exp)';
        statusBadge.style.color = '#22543d';
      }

      if (payloadObj.iat) {
        iatBadge.textContent = formatTimestamp(payloadObj.iat);
      } else {
        iatBadge.textContent = 'N/A';
      }

      detailsCard.style.display = 'block';
      setMsg('Token decoded successfully.', 'success');
    } catch (err) {
      console.error(err);
      setMsg('Failed to parse token. Invalid Base64URL encoding or corrupted JSON.', 'error');
      detailsCard.style.display = 'none';
    }
  }

  function createSampleToken() {
    const header = {
      alg: 'HS256',
      typ: 'JWT'
    };
    const now = Math.floor(Date.now() / 1000);
    const payload = {
      sub: 'usr_987654321',
      name: 'Alex Developer',
      role: 'admin',
      iss: 'https://niktool.in',
      iat: now,
      exp: now + 3600
    };

    const headerB64 = base64UrlEncode(JSON.stringify(header));
    const payloadB64 = base64UrlEncode(JSON.stringify(payload));
    const sampleSig = 'dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk';

    inputEl.value = `${headerB64}.${payloadB64}.${sampleSig}`;
    decodeJWT();
  }

  decodeBtn.addEventListener('click', decodeJWT);
  sampleBtn.addEventListener('click', createSampleToken);

  inputEl.addEventListener('input', () => {
    if (inputEl.value.trim().split('.').length === 3) {
      decodeJWT();
    }
  });

  clearBtn.addEventListener('click', () => {
    inputEl.value = '';
    headerOutput.value = '';
    payloadOutput.value = '';
    signatureOutput.value = '';
    detailsCard.style.display = 'none';
    setMsg('Cleared.');
  });

  copyHeaderBtn.addEventListener('click', () => {
    if (window.NikTool && typeof window.NikTool.copy === 'function') {
      window.NikTool.copy(headerOutput.value, copyHeaderBtn);
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(headerOutput.value);
    }
    setMsg('Header JSON copied to clipboard.', 'success');
  });

  copyPayloadBtn.addEventListener('click', () => {
    if (window.NikTool && typeof window.NikTool.copy === 'function') {
      window.NikTool.copy(payloadOutput.value, copyPayloadBtn);
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(payloadOutput.value);
    }
    setMsg('Payload JSON copied to clipboard.', 'success');
  });
})();

k-means-clustering-inertia-elbow-silhoue.js:
(() => {
  'use strict';
  const wcEl = document.getElementById('km-wcss');
  const kResEl = document.getElementById('km-res-k'), dpResEl = document.getElementById('km-res-drops');

  function update() {
    const wcss = wcEl.value.split(',').map(s => parseFloat(s.trim())).filter(n => !isNaN(n) && n > 0);
    if (wcss.length < 3) return;

    // Differences:
    const diffs = [];
    for (let i = 0; i < wcss.length - 1; i++) {
      diffs.push(wcss[i] - wcss[i+1]);
    }

    // Second differences (acceleration drop):
    const diff2 = [];
    for (let i = 0; i < diffs.length - 1; i++) {
      diff2.push(diffs[i] - diffs[i+1]);
    }

    let maxIdx = 0, maxVal = -Infinity;
    for (let i = 0; i < diff2.length; i++) {
      if (diff2[i] > maxVal) {
        maxVal = diff2[i];
        maxIdx = i;
      }
    }

    const optimalK = maxIdx + 2; // K is 1-based, second diff at index i corresponds to K = i + 2

    const dropsDesc = diffs.map((d, idx) => 'K' + (idx+1) + '→K' + (idx+2) + ': -' + Math.round(d)).join(' | ');

    kResEl.textContent = 'Optimal K = ' + optimalK + ' (Elbow Point)';
    dpResEl.textContent = dropsDesc + ' (Inertia K=' + optimalK + ': ' + wcss[optimalK - 1] + ')';
  }

  wcEl.addEventListener('input', update);
  update();
})();

k-nearest-neighbors-knn-distance-classif.js:
(() => {
  'use strict';
  const qEl = document.getElementById('kn-q'), kEl = document.getElementById('kn-k');
  const clResEl = document.getElementById('kn-res-class'), dsResEl = document.getElementById('kn-res-dist');

  // Hardcoded training sample set: [x, y, label]
  const trainData = [
    [1.0, 2.0, 'Red'],
    [2.0, 3.0, 'Red'],
    [3.0, 5.0, 'Red'],
    [5.0, 4.0, 'Blue'],
    [6.0, 6.0, 'Blue'],
    [7.0, 5.0, 'Blue']
  ];

  function update() {
    const qParts = qEl.value.split(',').map(s => parseFloat(s.trim())).filter(n => !isNaN(n));
    const K = parseInt(kEl.value, 10);

    if (qParts.length < 2 || isNaN(K) || K < 1) return;

    const qx = qParts[0], qy = qParts[1];

    // Compute Euclidean distance to all training points:
    const distances = trainData.map(pt => {
      const d = Math.sqrt(Math.pow(qx - pt[0], 2) + Math.pow(qy - pt[1], 2));
      return { pt: pt, dist: d, label: pt[2] };
    });

    distances.sort((a, b) => a.dist - b.dist);
    const kNearest = distances.slice(0, K);

    let redVotes = 0, blueVotes = 0;
    kNearest.forEach(n => {
      if (n.label === 'Red') redVotes++;
      else blueVotes++;
    });

    const winner = redVotes >= blueVotes ? 'RED' : 'BLUE';
    const desc = kNearest.map(n => '(' + n.pt[0] + ',' + n.pt[1] + ') ' + n.label + ' d=' + n.dist.toFixed(2)).join(' | ');

    clResEl.textContent = 'Class: ' + winner + ' (' + redVotes + ' Red / ' + blueVotes + ' Blue votes)';
    dsResEl.textContent = 'Nearest ' + K + ': ' + desc;
  }

  qEl.addEventListener('input', update);
  kEl.addEventListener('input', update);
  update();
})();

kalman-filter-1d-state-estimate-measurem.js:
(() => {
  'use strict';
  const xEl = document.getElementById('kf-x'), pEl = document.getElementById('kf-p');
  const zEl = document.getElementById('kf-z'), rEl = document.getElementById('kf-r');
  const xpResEl = document.getElementById('kf-res-xpost'), gnResEl = document.getElementById('kf-res-gain');

  function update() {
    const x_prior = parseFloat(xEl.value), P_prior = parseFloat(pEl.value);
    const z = parseFloat(zEl.value), R = parseFloat(rEl.value);

    if (isNaN(x_prior) || isNaN(P_prior) || isNaN(z) || isNaN(R) || P_prior < 0 || R <= 0) return;

    // Measurement innovation / residual: y = z - x_prior
    const innovation = z - x_prior;

    // Kalman gain: K_k = P_prior / ( P_prior + R )
    const K_k = P_prior / (P_prior + R);

    // Posterior state estimate: x_post = x_prior + K_k * innovation
    const x_post = x_prior + (K_k * innovation);

    // Posterior variance: P_post = (1 - K_k) * P_prior
    const P_post = (1.0 - K_k) * P_prior;

    const unc_reduction_pct = P_prior > 0 ? ((P_prior - P_post) / P_prior) * 100.0 : 0;

    xpResEl.textContent = 'Updated State x̂_post = ' + x_post.toFixed(2);
    gnResEl.textContent = 'Gain K_k = ' + K_k.toFixed(3) + ' | Variance: ' + P_prior.toFixed(2) + ' → ' + P_post.toFixed(2) + ' (-' + unc_reduction_pct.toFixed(1) + '% Error Uncertainty | Residual = ' + (innovation >= 0 ? '+' : '') + innovation.toFixed(1) + ')';
  }

  [xEl, pEl, zEl, rEl].forEach(el => el.addEventListener('input', update));
  update();
})();

