    const power_thermal_kW = (Q_CH4_m3_yr * 36.0) / 31536.0;
    const power_electric_MW = (power_thermal_kW * 0.38) / 1000.0;

    qResEl.textContent = 'Methane Q = ' + (Q_CH4_m3_yr / 1e6).toFixed(2) + ' × 10⁶ m³/year (' + Math.round(Q_CH4_m3_hr) + ' m³/hr)';
