﻿(function() {
  'use strict';
  var slug = 'lcm-hcf-calculator';
  var aEl = document.getElementById(slug + '-input');
  var bEl = document.getElementById(slug + '-b');
  var outputEl = document.getElementById(slug + '-output');
  var msgEl = document.getElementById(slug + '-message');
  var btn = document.getElementById('primary-action-btn');
  var copyBtn = document.getElementById('copy-output');
  var clearBtn = document.getElementById('clear-text');
  function setMsg(t, e){ msgEl.textContent=t; msgEl.classList.toggle('is-error', !!e); }
  function gcd(a, b) { while(b){ var t=b; b=a%b; a=t; } return a; }
  function primeFactors(n) {
    var factors = [];
    for (var i = 2; i <= n; i++) {
      while (n % i === 0) { factors.push(i); n = n / i; }
    }
    return factors;
  }
  btn.addEventListener('click', function() {
    var a = parseInt(aEl.value, 10), b = parseInt(bEl.value, 10);
    if (isNaN(a) || isNaN(b)) { setMsg('Please enter both numbers.', true); outputEl.value=''; copyBtn.disabled=true; return; }
    if (a < 1 || b < 1) { setMsg('Both numbers must be positive integers.', true); return; }
    var hcf = gcd(a, b);
    var lcm = (a / hcf) * b;
    var out = 'Numbers: ' + a + ' and ' + b + '\n\n';
    out += 'HCF (GCD): ' + hcf + '\n';
    out += 'LCM: ' + lcm + '\n\n';
    out += 'Prime Factorization:\n';
    out += a + ' = ' + primeFactors(a).join(' x ') + '\n';
    out += b + ' = ' + primeFactors(b).join(' x ') + '\n\n';
    out += 'Verification:\n';
    out += 'HCF x LCM = ' + hcf + ' x ' + lcm + ' = ' + (hcf * lcm) + '\n';
    out += 'a x b = ' + a + ' x ' + b + ' = ' + (a * b) + '\n';
    out += 'HCF x LCM = a x b: ' + (hcf * lcm === a * b ? 'TRUE' : 'FALSE');
    outputEl.value = out;
    copyBtn.disabled = false;
    setMsg('HCF and LCM calculated.');
  });
  copyBtn.addEventListener('click', function() { if (window.NikTool && typeof window.NikTool.copy === 'function') { window.NikTool.copy(outputEl.value, copyBtn); } else if (navigator.clipboard) { navigator.clipboard.writeText(outputEl.value); } setMsg('Result copied.'); });
  clearBtn.addEventListener('click', function() { aEl.value=''; bEl.value=''; outputEl.value=''; copyBtn.disabled=true; setMsg('Cleared.'); });
})();

le-chatelier-equilibrium-constant-van-t-.js:
(() => {
  'use strict';
  const dhEl = document.getElementById('vh-dh'), k1El = document.getElementById('vh-k1');
  const t1El = document.getElementById('vh-t1'), t2El = document.getElementById('vh-t2');
  const k2ResEl = document.getElementById('vh-res-k2'), shResEl = document.getElementById('vh-res-shift');

  const R = 8.314462618; // J / (mol * K)

  function update() {
    const dH_kJ = parseFloat(dhEl.value), K1 = parseFloat(k1El.value);
    const T1_C = parseFloat(t1El.value), T2_C = parseFloat(t2El.value);

    if (isNaN(dH_kJ) || isNaN(K1) || isNaN(T1_C) || isNaN(T2_C) || K1 <= 0 || T1_C < -273.15 || T2_C < -273.15) return;

    const T1_K = T1_C + 273.15;
    const T2_K = T2_C + 273.15;
    const dH_J = dH_kJ * 1000.0;

    // Van 't Hoff isochore: ln(K2 / K1) = - (dH / R) * ( 1/T2 - 1/T1 )
    const delta_inv_T = (1.0 / T2_K) - (1.0 / T1_K);
    const ln_ratio = -(dH_J / R) * delta_inv_T;
    const ratio = Math.exp(ln_ratio);
    const K2 = K1 * ratio;

    let shift = '', color = '#22543d';
    if (dH_kJ < 0) {
      shift = 'EXOTHERMIC (ΔH° < 0): Heating from ' + T1_C + '°C to ' + T2_C + '°C shifts equilibrium LEFT (K dropped ' + (1/ratio).toExponential(2) + '×)';
      color = '#ea580c';
    } else if (dH_kJ > 0) {
      shift = 'ENDOTHERMIC (ΔH° > 0): Heating from ' + T1_C + '°C to ' + T2_C + '°C shifts equilibrium RIGHT (K increased ' + ratio.toExponential(2) + '×)';
      color = '#22543d';
    } else {
      shift = 'ATHERMIC (ΔH° = 0): Temperature has zero effect on equilibrium constant';
      color = '#2563eb';
    }

    k2ResEl.textContent = 'Target K₂ = ' + (K2 < 0.01 || K2 > 10000 ? K2.toExponential(2) : K2.toFixed(3));
    shResEl.textContent = shift;
    shResEl.style.color = color;
  }

  [dhEl, k1El, t1El, t2El].forEach(el => el.addEventListener('input', update));
  update();
})();

lead-lag-compensator-frequency-response-.js:
(() => {
  'use strict';
  const phiEl = document.getElementById('ll-phi'), wmEl = document.getElementById('ll-wm');
  const cpResEl = document.getElementById('ll-res-comp'), alResEl = document.getElementById('ll-res-alpha');

  function update() {
    const phi_m_deg = parseFloat(phiEl.value), omega_m = parseFloat(wmEl.value);
    if (isNaN(phi_m_deg) || isNaN(omega_m) || phi_m_deg <= 0 || phi_m_deg >= 90 || omega_m <= 0) return;

    const phi_m_rad = (phi_m_deg * Math.PI) / 180.0;

    // Attenuation factor: alpha = ( 1 - sin(phi_m) ) / ( 1 + sin(phi_m) )
    const sin_phi = Math.sin(phi_m_rad);
    const alpha = (1.0 - sin_phi) / (1.0 + sin_phi);

    // Center frequency: omega_m = 1 / ( T * sqrt(alpha) ) => T = 1 / ( omega_m * sqrt(alpha) )
    const T = 1.0 / (omega_m * Math.sqrt(alpha));

    // Zero location: z = 1 / T
    const zero_loc = 1.0 / T;

    // Pole location: p = 1 / ( alpha * T )
    const pole_loc = 1.0 / (alpha * T);

    // High frequency gain in dB: 20 * log10( 1 / alpha )
    const gain_dB = 20.0 * Math.log10(1.0 / alpha);

    cpResEl.textContent = 'G_c(s) = (s + ' + zero_loc.toFixed(1) + ') / (s + ' + pole_loc.toFixed(1) + ')';
    alResEl.textContent = 'α = ' + alpha.toFixed(4) + ' | Zero: -' + zero_loc.toFixed(1) + ', Pole: -' + pole_loc.toFixed(1) + ' rad/s (+ ' + gain_dB.toFixed(1) + ' dB Gain Boost)';
  }

  phiEl.addEventListener('input', update));
  wmEl.addEventListener('input', update);
  update();
})();

