(() => {
  'use strict';
  const vmEl = document.getElementById('lb-vmax'), kmEl = document.getElementById('lb-km'), mdEl = document.getElementById('lb-mode');
  const eqResEl = document.getElementById('lb-res-eq'), intResEl = document.getElementById('lb-res-int');

  function update() {
    const base_vmax = parseFloat(vmEl.value), base_km = parseFloat(kmEl.value);
    const mode = mdEl.value;

    if (isNaN(base_vmax) || isNaN(base_km) || base_vmax <= 0 || base_km <= 0) return;

    let V_max = base_vmax;
    let K_m = base_km;

    if (mode === 'comp') {
      K_m = base_km * 2.0; // Competitive increases apparent Km
    } else if (mode === 'noncomp') {
      V_max = base_vmax / 2.0; // Non-competitive reduces Vmax
    } else if (mode === 'uncomp') {
      K_m = base_km / 2.0;
      V_max = base_vmax / 2.0;
    }

    // Lineweaver-Burk: 1/V = (Km / Vmax) * (1/[S]) + (1 / Vmax)
    const slope = K_m / V_max;
    const y_intercept = 1.0 / V_max;
    const x_intercept = -1.0 / K_m;

    eqResEl.textContent = '1/V = ' + slope.toFixed(3) + '·(1/[S]) + ' + y_intercept.toFixed(3);
    intResEl.textContent = 'Apparent K_m = ' + K_m.toFixed(2) + ' mM | V_max = ' + V_max.toFixed(1) + ' μmol/min (y-int: ' + y_intercept.toFixed(3) + ', x-int: ' + x_intercept.toFixed(3) + ' mM⁻¹)';
  }

  [vmEl, kmEl].forEach(el => el.addEventListener('input', update));
  mdEl.addEventListener('change', update);
  update();
})();

link-margin-friis-free-space-path-loss-e.js:
(() => {
  'use strict';
  const ptxEl = document.getElementById('lk-ptx'), gtxEl = document.getElementById('lk-gtx');
  const grxEl = document.getElementById('lk-grx'), fEl = document.getElementById('lk-f'), dEl = document.getElementById('lk-d');
  const prResEl = document.getElementById('lk-res-prx'), fsResEl = document.getElementById('lk-res-fspl');

  const c_light = 2.99792458e8;

  function update() {
    const P_tx_W = parseFloat(ptxEl.value), G_tx_dBi = parseFloat(gtxEl.value);
    const G_rx_dBi = parseFloat(grxEl.value), f_GHz = parseFloat(fEl.value), d_Mkm = parseFloat(dEl.value);

    if (isNaN(P_tx_W) || isNaN(G_tx_dBi) || isNaN(G_rx_dBi) || isNaN(f_GHz) || isNaN(d_Mkm) || P_tx_W <= 0 || f_GHz <= 0 || d_Mkm <= 0) return;

    // Transmit power in dBm:
    const P_tx_dBm = 10.0 * Math.log10(P_tx_W * 1000.0);
    const EIRP_dBW = (10.0 * Math.log10(P_tx_W)) + G_tx_dBi;

    // Distance in meters:
    const d_m = d_Mkm * 1e9;
    const f_Hz = f_GHz * 1e9;

    // Free space path loss: FSPL = 20*log10(d) + 20*log10(f) + 20*log10(4*pi/c)  [dB]
    const FSPL_dB = (20.0 * Math.log10(d_m)) + (20.0 * Math.log10(f_Hz)) + (20.0 * Math.log10(4.0 * Math.PI / c_light));

    // Friis received power: P_rx = P_tx + G_tx + G_rx - FSPL  [dBm]
    const P_rx_dBm = P_tx_dBm + G_tx_dBi + G_rx_dBi - FSPL_dB;
    const P_rx_Watts = Math.pow(10.0, (P_rx_dBm - 30.0) / 10.0);

    prResEl.textContent = 'Received P_rx = ' + P_rx_dBm.toFixed(1) + ' dBm (' + P_rx_Watts.toExponential(2) + ' W)';
    fsResEl.textContent = 'Path Loss FSPL = ' + FSPL_dB.toFixed(1) + ' dB | EIRP = +' + EIRP_dBW.toFixed(1) + ' dBW (d=' + d_Mkm + ' Million km @ ' + f_GHz + ' GHz)';
  }

  [ptxEl, gtxEl, grxEl, fEl, dEl].forEach(el => el.addEventListener('input', update));
  update();
})();

linked-list-visualizer.js:
﻿(function(){
'use strict';
let list=[];
const display=document.getElementById('ll-display'),msg=document.getElementById('ll-msg'),
      valIn=document.getElementById('ll-val'),countEl=document.getElementById('ll-count');

function render(hlIdx){
  display.innerHTML='';
  if(!list.length){display.innerHTML='<span style="opacity:0.4;">Empty list — add nodes to begin</span>';countEl.textContent='0';return;}
  list.forEach((v,i)=>{
    const node=document.createElement('div');
    node.style.cssText='display:flex;align-items:center;';
    const box=document.createElement('div');
    box.style.cssText='padding:10px 16px;border-radius:6px;font-weight:600;background:'+(i===hlIdx?'#ffd54f':'#37474f')+';color:'+(i===hlIdx?'#111':'#eee')+';transition:all 0.3s;';
    box.textContent=v;
    const arrow=document.createElement('span');
    arrow.style.cssText='margin:0 6px;opacity:0.5;font-size:1.2rem;';
    arrow.textContent=i<list.length-1?'→':'→ ∅';
    node.appendChild(box);node.appendChild(arrow);
    display.appendChild(node);
  });
  countEl.textContent=list.length;
}
document.getElementById('ll-add').addEventListener('click',()=>{
  const v=valIn.value.trim();if(!v){msg.textContent='Enter a value.';return;}
  list.push(+v||v);render(list.length-1);msg.textContent='Added "'+v+'" at the end.';valIn.value='';valIn.focus();
});
document.getElementById('ll-add-front').addEventListener('click',()=>{
  const v=valIn.value.trim();if(!v){msg.textContent='Enter a value.';return;}
  list.unshift(+v||v);render(0);msg.textContent='Added "'+v+'" at the front.';valIn.value='';valIn.focus();
});
document.getElementById('ll-del').addEventListener('click',()=>{
  if(!list.length){msg.textContent='List is empty.';return;}
  const v=list.pop();render();msg.textContent='Deleted "'+v+'" from the end.';
});
document.getElementById('ll-reverse').addEventListener('click',()=>{
  if(!list.length){msg.textContent='Nothing to reverse.';return;}
  list.reverse();render();msg.textContent='List reversed! Pointers updated.';
});
document.getElementById('ll-clear').addEventListener('click',()=>{
  list=[];render();msg.textContent='List cleared.';
});
render();
})();

