(() => {
  'use strict';
  const x0El = document.getElementById('log-x0'), xnEl = document.getElementById('log-xn'), nEl = document.getElementById('log-n');
  const zResEl = document.getElementById('log-res-zeta'), dResEl = document.getElementById('log-res-delta');

  function update() {
    const x0 = parseFloat(x0El.value), xn = parseFloat(xnEl.value), n = parseFloat(nEl.value);
    if (isNaN(x0) || isNaN(xn) || isNaN(n) || x0 <= 0 || xn <= 0 || n <= 0 || xn >= x0) return;

    // Logarithmic decrement delta = (1 / n) * ln(x0 / xn)
    const delta = (1 / n) * Math.log(x0 / xn);

    // Damping ratio zeta = delta / sqrt( 4*pi^2 + delta^2 )
    const zeta = delta / Math.sqrt((4 * Math.pow(Math.PI, 2)) + Math.pow(delta, 2));
    const zetaPct = zeta * 100;

    const dropPct = ((x0 - xn) / x0) * 100;

    zResEl.textContent = 'ζ = ' + zetaPct.toFixed(2) + '% Damping Ratio';
    dResEl.textContent = 'Log Decrement δ = ' + delta.toFixed(4) + ' (' + dropPct.toFixed(1) + '% Decay from ' + x0 + 'mm to ' + xn + 'mm across ' + n + ' Cycles)';
  }

  [x0El, xnEl, nEl].forEach(el => el.addEventListener('input', update));
  update();
})();

logistic-map-bifurcation-feigenbaum-cons.js:
(() => {
  'use strict';
  const rEl = document.getElementById('log-r'), x0El = document.getElementById('log-x0');
  const regResEl = document.getElementById('log-res-reg'), orbResEl = document.getElementById('log-res-orb');

  const delta_feigenbaum = 4.669201609;
  const r_infinity = 3.5699456;

  function update() {
    const r = parseFloat(rEl.value), x0 = parseFloat(x0El.value);
    if (isNaN(r) || isNaN(x0) || r < 0 || r > 4.0 || x0 <= 0 || x0 >= 1.0) return;

    // Iterate logistic map x_(n+1) = r * x_n * (1 - x_n) for 300 warm-up steps
    let x = x0;
    for (let i = 0; i < 300; i++) {
      x = r * x * (1.0 - x);
    }

    // Collect last 16 values to detect orbit period
    const orbit = [];
    for (let i = 0; i < 16; i++) {
      x = r * x * (1.0 - x);
      orbit.push(x);
    }

    let regime = '';
    let color = '#22543d';

    if (r < 3.0) {
      regime = 'PERIOD-1 FIXED POINT (Stable single equilibrium x* = ' + (1.0 - 1.0/r).toFixed(3) + ')';
      color = '#22543d';
    } else if (r < 3.449) {
      regime = 'PERIOD-2 STABLE CYCLE (Oscillates between 2 values)';
      color = '#2563eb';
    } else if (r < 3.544) {
      regime = 'PERIOD-4 STABLE CYCLE (Oscillates between 4 values)';
      color = '#2563eb';
    } else if (r < r_infinity) {
      regime = 'PERIOD-8 / PERIOD-16 CASCADE (Dense period doubling toward chaos)';
      color = '#d97706';
    } else if (r >= 3.8284 && r <= 3.8415) {
      regime = 'PERIOD-3 TANGENT WINDOW ("Period 3 Implies Chaos" - Li-Yorke Theorem)';
      color = '#ea580c';
    } else {
      regime = 'FULLY DEVELOPED DETERMINISTIC CHAOS (Aperiodic, sensitive to initial x₀)';
      color = '#c53030';
    }

    regResEl.textContent = regime;
    regResEl.style.color = color;
    orbResEl.textContent = 'Orbit Samples: {' + orbit.slice(0, 4).map(v => v.toFixed(3)).join(', ') + '} | Feigenbaum δ = ' + delta_feigenbaum.toFixed(4) + ' (r_∞ = 3.5699)';
  }

  rEl.addEventListener('input', update);
  x0El.addEventListener('input', update);
  update();
})();

logistic-regression-sigmoid-cross-entrop.js:
(() => {
  'use strict';
  const zEl = document.getElementById('lr-z'), yEl = document.getElementById('lr-y');
  const prResEl = document.getElementById('lr-res-prob'), lsResEl = document.getElementById('lr-res-loss');

  function update() {
    const z = parseFloat(zEl.value), y = parseFloat(yEl.value);
    if (isNaN(z) || isNaN(y)) return;

    // Sigmoid function: p = 1 / (1 + exp(-z))
    const p = 1.0 / (1.0 + Math.exp(-z));

    // Odds = p / (1 - p) = exp(z)
    const odds = Math.exp(z);

    // Binary cross-entropy loss: L = -( y * ln(p) + (1-y) * ln(1-p) )
    const eps = 1e-15;
    const p_safe = Math.max(eps, Math.min(1.0 - eps, p));
    const loss = -( (y * Math.log(p_safe)) + ((1.0 - y) * Math.log(1.0 - p_safe)) );

    // Derivative dL/dz = p - y
    const grad = p - y;

    prResEl.textContent = 'Probability p = ' + p.toFixed(4) + ' (' + (p * 100).toFixed(2) + '%)';
    lsResEl.textContent = 'Log Loss ℒ = ' + loss.toFixed(4) + ' | Odds = ' + odds.toFixed(2) + ':1 | Gradient dℒ/dz = ' + (grad >= 0 ? '+' : '') + grad.toFixed(4) + ' (y = ' + y + ')';
  }

  zEl.addEventListener('input', update);
  yEl.addEventListener('change', update);
  update();
})();
